def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    INF = float('-inf')
    # prev[g][p][b] = max score after processing messages,
    # with g trailing drops, p=1 if last message kept, b = length used
    prev = [[[INF] * (budget + 1) for _ in range(2)] for _ in range(max_gap + 1)]
    prev[0][0][0] = 0

    for i in range(n):
        length, value, pinned = messages[i]
        curr = [[[INF] * (budget + 1) for _ in range(2)] for _ in range(max_gap + 1)]
        for g in range(max_gap + 1):
            for p in range(2):
                for b in range(budget + 1):
                    sc = prev[g][p][b]
                    if sc == INF:
                        continue
                    # drop (only if not pinned)
                    if not pinned:
                        ng = g + 1
                        if ng <= max_gap:
                            if sc > curr[ng][0][b]:
                                curr[ng][0][b] = sc
                    # keep
                    nb = b + length
                    if nb <= budget:
                        nsc = sc + value
                        if p == 1:
                            nsc += bonus
                        if nsc > curr[0][1][nb]:
                            curr[0][1][nb] = nsc
        prev = curr

    max_sc = INF
    for g in range(max_gap + 1):
        for p in range(2):
            for b in range(budget + 1):
                if prev[g][p][b] > max_sc:
                    max_sc = prev[g][p][b]

    return None if max_sc == INF else int(max_sc)

def run_kiosk(levels, threshold, patience, arrivals):
    if not arrivals:
        return []
    prev_t = -1
    for t, _, _ in arrivals:
        if t < prev_t:
            raise ValueError("arrivals not sorted by time")
        prev_t = t

    from collections import deque
    S = len(levels)
    slots = [(0, c) for c in levels]
    queue = deque()
    records = []
    arr_idx = 0
    N = len(arrivals)
    current_time = 0

    def best_slot(t):
        best_i = -1
        best_c = -1
        for i in range(S):
            pt, pc = slots[i]
            c = min(100, pc + (t - pt))
            if c >= threshold and c > best_c:
                best_c = c
                best_i = i
        return best_i

    while True:
        # 1. Serve the queue while possible
        while queue:
            bs = best_slot(current_time)
            if bs < 0:
                break
            _, name, ch = queue.popleft()
            records.append((name, "SWAP", current_time, bs))
            slots[bs] = (current_time, ch)

        # 2. Handle arrivals at current_time
        while arr_idx < N and arrivals[arr_idx][0] == current_time:
            t, name, ch = arrivals[arr_idx]
            arr_idx += 1
            if not queue:
                bs = best_slot(current_time)
                if bs >= 0:
                    records.append((name, "SWAP", current_time, bs))
                    slots[bs] = (current_time, ch)
                    continue
            queue.append((t, name, ch))

        # 3. Give up expired drones
        while queue and queue[0][0] + patience <= current_time:
            _, name, _ = queue.popleft()
            records.append((name, "LEFT", current_time))

        if arr_idx >= N and not queue:
            break

        # Determine next time to jump to
        next_time = None
        if arr_idx < N:
            next_time = arrivals[arr_idx][0]
        if queue:
            exp = queue[0][0] + patience
            if next_time is None or exp < next_time:
                next_time = exp
            for i in range(S):
                pt, pc = slots[i]
                if pc >= threshold:
                    ra = pt
                else:
                    ra = pt + (threshold - pc)
                if ra > current_time and (next_time is None or ra < next_time):
                    next_time = ra

        if next_time is None:
            break
        current_time = next_time

    return records

def run_lock_manager(ops):
    from collections import defaultdict, deque
    logs = []
    tx_state = {}
    tx_locks = defaultdict(dict)
    tx_wait = {}
    resources = defaultdict(lambda: {'holders': {}, 'queue': [], 'num_upg': 0})
    adj = {}
    rev = defaultdict(set)

    def compatible(m1, m2):
        return m1 == 'S' and m2 == 'S'

    def clear_wait(tx):
        if tx in adj:
            for t in adj[tx]:
                rev[t].discard(tx)
                if not rev[t]:
                    del rev[t]
            del adj[tx]
        if tx in tx_wait:
            del tx_wait[tx]

    def recompute_res(rname):
        r = resources[rname]
        if not r['queue']:
            return
        prev = []
        holders = r['holders']
        for w, m in r['queue']:
            if w in adj:
                for t in adj[w]:
                    rev[t].discard(w)
                    if not rev[t]:
                        del rev[t]
                del adj[w]
            outs = set()
            for h, hm in holders.items():
                if h != w and not compatible(m, hm):
                    outs.add(h)
            outs.update(prev)
            adj[w] = outs
            for t in outs:
                rev[t].add(w)
            prev.append(w)

    def is_grantable(rname, tx, mode):
        holders = resources[rname]['holders']
        for h, hm in holders.items():
            if h != tx and not compatible(mode, hm):
                return False
        return True

    def process_queue(rname, i):
        r = resources[rname]
        while r['queue']:
            tx, mode = r['queue'][0]
            if not is_grantable(rname, tx, mode):
                break
            was_upg = r['num_upg'] > 0
            del r['queue'][0]
            if was_upg:
                r['num_upg'] -= 1
            clear_wait(tx)
            tx_state[tx] = 'ACTIVE'
            r['holders'][tx] = mode
            tx_locks[tx][rname] = mode
            logs.append(("GRANT", i, tx, rname, mode))
        recompute_res(rname)

    def release(tx, i):
        affected = set()
        if tx in tx_wait:
            resn, _ = tx_wait[tx]
            r = resources[resn]
            idx = next(j for j, (t, _) in enumerate(r['queue']) if t == tx)
            if idx < r['num_upg']:
                r['num_upg'] -= 1
            del r['queue'][idx]
            clear_wait(tx)
            affected.add(resn)
        if tx in tx_locks:
            for resn in list(tx_locks[tx]):
                del resources[resn]['holders'][tx]
                affected.add(resn)
            tx_locks[tx].clear()
        for resn in sorted(affected):
            process_queue(resn, i)

    def get_reachable(source, adjac):
        seen = set()
        stk = [source]
        seen.add(source)
        while stk:
            u = stk.pop()
            for v in adjac.get(u, ()):
                if v not in seen:
                    seen.add(v)
                    stk.append(v)
        return seen

    def get_nodes_on_cycles(start):
        if start not in adj:
            return set()
        F = get_reachable(start, adj)
        B = get_reachable(start, rev)
        inter = F & B
        if len(inter) > 1:
            return inter
        return set()

    def check_deadlocks(i, new_w):
        while True:
            nodes = get_nodes_on_cycles(new_w)
            if not nodes:
                break
            victim = max(nodes)
            logs.append(("ABORT", i, victim))
            release(victim, i)
            tx_state[victim] = 'FINISHED'

    for i, op in enumerate(ops):
        typ = op[0]
        if typ == 'COMMIT':
            tx = op[1]
        else:
            mode = typ
            tx = op[1]
            res = op[2]

        state = tx_state.get(tx)
        if state in ('WAITING', 'FINISHED'):
            logs.append(("IGNORED", i, tx))
            continue
        if state is None:
            tx_state[tx] = 'ACTIVE'

        if typ == 'COMMIT':
            logs.append(("COMMIT", i, tx))
            release(tx, i)
            tx_state[tx] = 'FINISHED'
            continue

        r = resources[res]
        heldmode = tx_locks[tx].get(res)
        if heldmode == 'X' or (heldmode == 'S' and mode == 'S'):
            logs.append(("HELD", i, tx, res))
            continue

        if heldmode == 'S' and mode == 'X':
            if len(r['holders']) == 1:
                r['holders'][tx] = 'X'
                tx_locks[tx][res] = 'X'
                logs.append(("GRANT", i, tx, res, "X"))
                recompute_res(res)
                continue
            else:
                pos = r['num_upg']
                r['queue'].insert(pos, (tx, 'X'))
                r['num_upg'] += 1
                tx_wait[tx] = (res, 'X')
                tx_state[tx] = 'WAITING'
                logs.append(("WAIT", i, tx, res, "X"))
                recompute_res(res)
                check_deadlocks(i, tx)
                continue

        if not r['queue'] and all(compatible(mode, hm) for hm in r['holders'].values()):
            r['holders'][tx] = mode
            tx_locks[tx][res] = mode
            logs.append(("GRANT", i, tx, res, mode))
            recompute_res(res)
            continue
        else:
            r['queue'].append((tx, mode))
            tx_wait[tx] = (res, mode)
            tx_state[tx] = 'WAITING'
            logs.append(("WAIT", i, tx, res, mode))
            recompute_res(res)
            check_deadlocks(i, tx)
            continue

    return logs

def simulate_vending(prices, stock, bank, events, timeout):
    from collections import defaultdict

    # Validate event times are non-decreasing
    prev_t = -1
    for t, kind, arg in events:
        if t < prev_t:
            raise ValueError("events not in non-decreasing time order")
        prev_t = t

    # Copy mutable state (do not mutate inputs)
    stock = dict(stock)
    bank_counts = {5: 0, 10: 0, 25: 0, 100: 0}
    for k, v in bank.items():
        bank_counts[k] = v

    escrow = []  # ordered list of coin values
    log = []
    last_activity = None  # time of most recent activity
    ACCEPTED = {5, 10, 25, 100}

    def escrow_total():
        return sum(escrow)

    def sorted_coins(coins):
        return tuple(sorted(coins, reverse=True))

    def do_timeout_return(at_time):
        nonlocal escrow, last_activity
        if escrow:
            coins = sorted_coins(escrow)
            log.append(("TIMEOUT", at_time, coins))
            escrow = []
            # timeout return is not an activity; last_activity stays

    def maybe_auto_return(before_t):
        """If escrow non-empty and last_activity + timeout <= before_t, return it."""
        nonlocal last_activity
        if escrow and last_activity is not None:
            ret_t = last_activity + timeout
            if ret_t <= before_t:
                do_timeout_return(ret_t)
                # after return escrow is empty; no further pending timeout

    def try_change(amount):
        """Greedy change from bank_counts. Returns (success, list_of_coins) or
        (False, None). Does not mutate bank_counts on failure; on success the
        caller has already moved escrow in, so we mutate bank on success path
        only after confirming, or we mutate a copy.

        Actually: we need to try without permanently taking if fail.
        Returns (ok, change_list) and if ok, bank_counts already reduced.
        """
        taken = []
        remaining = amount
        # work on a temporary copy
        temp = dict(bank_counts)
        for d in (100, 25, 10, 5):
            k = min(temp[d], remaining // d)
            if k:
                temp[d] -= k
                taken.extend([d] * k)
                remaining -= d * k
        if remaining == 0:
            # commit
            bank_counts.update(temp)
            return True, taken
        return False, None

    for t, kind, arg in events:
        # Auto-return before processing this event if due
        maybe_auto_return(t)

        if kind == "coin":
            v = arg
            if v not in ACCEPTED or len(escrow) >= 10:
                log.append(("REJECT", t, v))
                # not an activity
            else:
                escrow.append(v)
                last_activity = t

        elif kind == "select":
            s = arg
            # select is always an activity (whatever outcome)
            last_activity = t

            if s not in prices:
                log.append(("UNKNOWN", t, s))
            elif stock[s] == 0:
                log.append(("SOLD_OUT", t, s))
            else:
                price = prices[s]
                total = escrow_total()
                if total < price:
                    log.append(("NEED", t, price - total))
                else:
                    # Attempt sale: move ALL escrow into bank, then make change
                    saved_escrow = list(escrow)
                    saved_bank = dict(bank_counts)

                    for c in escrow:
                        bank_counts[c] += 1
                    escrow = []

                    change_needed = total - price
                    ok, change_coins = try_change(change_needed)
                    if ok:
                        stock[s] -= 1
                        log.append(("VEND", t, s, sorted_coins(change_coins)))
                        # escrow already empty
                    else:
                        # full rollback
                        bank_counts.clear()
                        bank_counts.update(saved_bank)
                        escrow = saved_escrow
                        log.append(("EXACT_ONLY", t, s))

        elif kind == "cancel":
            # cancel is always an activity
            last_activity = t
            if escrow:
                coins = sorted_coins(escrow)
                log.append(("RETURN", t, coins))
                escrow = []

        else:
            # unknown kind – spec doesn't say; ignore or treat as no-op
            pass

    # After last event, pending automatic return
    if escrow and last_activity is not None:
        do_timeout_return(last_activity + timeout)

    final_bank = (
        bank_counts[5],
        bank_counts[10],
        bank_counts[25],
        bank_counts[100],
    )
    return (log, final_bank)

import re

def evaluate_access(rules, requests) -> list[str]:
    NAME_RE = re.compile(r'^[a-z0-9_]+$')
    ACTION_WORD_RE = re.compile(r'^[a-z]+$')
    SEGMENT_RE = re.compile(r'^[a-z0-9._-]+$')
    RESOURCE_SEG_RE = re.compile(r'^([a-z0-9._-]+|\*|\*\*)$')

    def is_name(s):
        return isinstance(s, str) and bool(NAME_RE.match(s))

    def is_action_word(s):
        return isinstance(s, str) and bool(ACTION_WORD_RE.match(s))

    def parse_action_field(action):
        if action == '*':
            return '*'
        parts = action.split(',')
        if not parts or any(p == '' or not ACTION_WORD_RE.match(p) for p in parts):
            return None
        if '*' in parts:
            return None
        return parts

    def parse_resource(resource):
        if not isinstance(resource, str):
            return None
        if resource == '/':
            return []
        if not resource.startswith('/') or resource.endswith('/'):
            return None
        segs = resource[1:].split('/')
        if any(s == '' or not RESOURCE_SEG_RE.match(s) for s in segs):
            return None
        return segs

    def parse_path(path):
        if not isinstance(path, str):
            return None
        if path == '/':
            return []
        if not path.startswith('/') or path.endswith('/'):
            return None
        segs = path[1:].split('/')
        if any(s == '' or not SEGMENT_RE.match(s) for s in segs):
            return None
        return segs

    def parse_principal(principal):
        if principal == '*':
            return ('*', None)
        if principal.startswith('user:'):
            name = principal[5:]
            if is_name(name):
                return ('user', name)
            return None
        if principal.startswith('group:'):
            name = principal[6:]
            if is_name(name):
                return ('group', name)
            return None
        return None

    # --- Validation ---
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    parsed_rules = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
        effect, principal, action, resource = fields
        if effect not in ('ALLOW', 'DENY'):
            raise ValueError(f"rule {i}: bad effect {effect!r}")
        p = parse_principal(principal)
        if p is None:
            raise ValueError(f"rule {i}: bad principal {principal!r}")
        a = parse_action_field(action)
        if a is None:
            raise ValueError(f"rule {i}: bad action {action!r}")
        r = parse_resource(resource)
        if r is None:
            raise ValueError(f"rule {i}: bad resource {resource!r}")
        # specificity components
        L = sum(1 for s in r if s != '*' and s != '**')
        P = 2 if p[0] == 'user' else (1 if p[0] == 'group' else 0)
        A = 0 if a == '*' else 1
        parsed_rules.append({
            'index': i,
            'effect': effect,
            'principal': p,
            'action': a,
            'resource': r,
            'specificity': (L, P, A),
        })

    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req
        if not is_name(user):
            raise ValueError(f"request {j}: bad user {user!r}")
        if not isinstance(groups, list) or any(not is_name(g) for g in groups):
            raise ValueError(f"request {j}: bad groups")
        if not is_action_word(action):
            raise ValueError(f"request {j}: bad action {action!r}")
        path_segs = parse_path(path)
        if path_segs is None:
            raise ValueError(f"request {j}: bad path {path!r}")
        parsed_requests.append((user, groups, action, path_segs))

    # --- Resource matching (non-exponential) ---
    def resource_matches(pattern_segs, path_segs):
        """Match resource pattern against path using DP to avoid exponential backtracking."""
        m = len(pattern_segs)
        n = len(path_segs)
        # dp[i][j] = whether pattern[:i] matches path[:j]
        # Use two rows or a set of reachable path positions for each pattern position
        # reachable[j] means pattern prefix matches path[:j]
        reachable = {0}
        for i, pat in enumerate(pattern_segs):
            new_reachable = set()
            if pat == '**':
                # ** matches zero or more segments
                if not reachable:
                    return False
                min_j = min(reachable)
                # from any reachable j, can go to any k >= j
                for j in range(min_j, n + 1):
                    # check if some r in reachable with r <= j
                    # since we take min and go up, once we pass all reachable we need care
                    pass
                # Better: for each r in reachable, add all k from r to n
                for r in reachable:
                    for k in range(r, n + 1):
                        new_reachable.add(k)
            elif pat == '*':
                for r in reachable:
                    if r < n:
                        new_reachable.add(r + 1)
            else:
                for r in reachable:
                    if r < n and path_segs[r] == pat:
                        new_reachable.add(r + 1)
            reachable = new_reachable
            if not reachable:
                return False
        return n in reachable

    # --- Evaluation ---
    decisions = []
    for user, groups, action, path_segs in parsed_requests:
        matches = []
        for rule in parsed_rules:
            # principal
            ptype, pname = rule['principal']
            if ptype == '*':
                pass
            elif ptype == 'user':
                if pname != user:
                    continue
            elif ptype == 'group':
                if pname not in groups:
                    continue
            # action
            ra = rule['action']
            if ra != '*':
                if action not in ra:
                    continue
            # resource
            if not resource_matches(rule['resource'], path_segs):
                continue
            matches.append(rule)

        if not matches:
            decisions.append("DENY by default")
            continue

        max_spec = max(r['specificity'] for r in matches)
        best = [r for r in matches if r['specificity'] == max_spec]
        denies = [r for r in best if r['effect'] == 'DENY']
        if denies:
            i = min(r['index'] for r in denies)
            decisions.append(f"DENY by rule {i}")
        else:
            i = min(r['index'] for r in best)
            decisions.append(f"ALLOW by rule {i}")

    return decisions

from __future__ import annotations

import copy
import json
import re
from typing import Any

_IDENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def _type_name(v: Any) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "str"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    raise TypeError(f"unsupported value type: {type(v)}")


def _path_of(parent: str, name: str) -> str:
    if _IDENT_RE.fullmatch(name):
        return f"{parent}.{name}"
    return f"{parent}[{json.dumps(name, ensure_ascii=False)}]"


def _deep_copy(v: Any) -> Any:
    """Copy value; dicts/lists nested in lists are opaque (copied as-is)."""
    return copy.deepcopy(v)


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    def merge_dict(T: dict, O: dict, P: str, L: int) -> None:
        for K in O:
            if not isinstance(K, str):
                raise TypeError(f"layer {L}: non-string key at {P}")

            if K.startswith("-"):
                kind = "DELETE"
                NAME = K[1:]
            elif K.endswith("+"):
                kind = "APPEND"
                NAME = K[:-1]
            else:
                kind = "SET"
                NAME = K

            if NAME == "":
                raise ValueError(f"layer {L}: empty key name at {P}")

            Q = _path_of(P, NAME)
            V = O[K]

            if kind == "DELETE":
                if V is not None:
                    raise ValueError(
                        f"layer {L}: delete directive needs null at {Q}"
                    )
                if NAME in T:
                    del T[NAME]
                else:
                    warnings.append(
                        f"layer {L}: delete of missing key at {Q}"
                    )

            elif kind == "APPEND":
                if not isinstance(V, list):
                    raise ValueError(
                        f"layer {L}: append directive needs a list at {Q}"
                    )
                if NAME not in T:
                    T[NAME] = _deep_copy(V)
                elif isinstance(T[NAME], list):
                    T[NAME].extend(_deep_copy(V))
                else:
                    raise ValueError(
                        f"layer {L}: cannot append to {_type_name(T[NAME])} at {Q}"
                    )

            else:  # SET
                if NAME in T and _type_name(T[NAME]) != _type_name(V):
                    warnings.append(
                        f"layer {L}: type change at {Q}: "
                        f"{_type_name(T[NAME])} -> {_type_name(V)}"
                    )

                if isinstance(V, dict):
                    if NAME not in T or not isinstance(T[NAME], dict):
                        T[NAME] = {}
                    merge_dict(T[NAME], V, Q, L)
                else:
                    T[NAME] = _deep_copy(V)

    for L, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {L} is not a dict")
        merge_dict(result, layer, "$", L)

    return result, warnings

import re
from datetime import date

_OPENING_RE = re.compile(r'^-?(0|[1-9][0-9]{0,8})\.[0-9]{2}$')
_AMOUNT_RE = re.compile(r'^(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?$')
_DATE_RE = re.compile(r'^([0-9]{4})-([0-9]{2})-([0-9]{2})$')
_KINDS = frozenset({'credit', 'debit', 'fee'})


def _parse_opening(s: str) -> int:
    """Parse opening amount string to cents (int)."""
    neg = s.startswith('-')
    body = s[1:] if neg else s
    whole, frac = body.split('.')
    cents = int(whole) * 100 + int(frac)
    return -cents if neg else cents


def _parse_amount(s: str) -> int:
    """Parse entry amount string to cents (int). Must be > 0."""
    if '.' in s:
        whole, frac = s.split('.')
        if len(frac) == 1:
            frac = frac + '0'
        cents = int(whole) * 100 + int(frac)
    else:
        cents = int(s) * 100
    return cents


def _money(cents: int) -> str:
    """Format cents as MONEY string."""
    neg = cents < 0
    cents = abs(cents)
    whole = cents // 100
    frac = cents % 100
    # thousands separator
    w = f'{whole:,}'
    result = f'{w}.{frac:02d}'
    return f'-{result}' if neg else result


def _valid_date(s: str):
    """Return date object if valid Gregorian YYYY-MM-DD in 1900..2999, else None."""
    m = _DATE_RE.match(s)
    if not m:
        return None
    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if y < 1900 or y > 2999:
        return None
    try:
        return date(y, mo, d)
    except ValueError:
        return None


def _normalize_memo(memo: str) -> str:
    text = ' '.join(memo.split())
    if len(text) > 20:
        text = text[:19] + '~'
    return text.ljust(20)


def render_statement(opening, entries) -> list[str]:
    # --- validation ---
    if not isinstance(opening, str):
        raise TypeError('opening must be a str')
    if not _OPENING_RE.match(opening):
        raise ValueError('opening: bad amount ' + repr(opening))
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')

    validated = []  # list of (date_str, date_obj, kind, amount_cents, memo)
    prev_date = None
    for i, entry in enumerate(entries):
        if not isinstance(entry, tuple) or len(entry) != 4:
            raise TypeError(f'entry {i}: expected 4-tuple')
        d, kind, amount, memo = entry

        # date
        if not isinstance(d, str):
            raise ValueError(f'entry {i}: bad date {d!r}')
        d_obj = _valid_date(d)
        if d_obj is None:
            raise ValueError(f'entry {i}: bad date {d!r}')
        if prev_date is not None and d_obj < prev_date:
            raise ValueError(f'entry {i}: date out of order')
        prev_date = d_obj

        # kind
        if kind not in _KINDS:
            raise ValueError(f'entry {i}: bad kind {kind!r}')

        # amount
        if not isinstance(amount, str) or not _AMOUNT_RE.match(amount):
            raise ValueError(f'entry {i}: bad amount {amount!r}')
        amt_cents = _parse_amount(amount)
        if amt_cents == 0:
            raise ValueError(f'entry {i}: bad amount {amount!r}')

        # memo
        if not isinstance(memo, str):
            raise ValueError(f'entry {i}: bad memo')
        if not memo.split():
            raise ValueError(f'entry {i}: bad memo')
        for ch in memo:
            cp = ord(ch)
            if cp < 32 or cp == 127:
                raise ValueError(f'entry {i}: bad memo')

        validated.append((d, d_obj, kind, amt_cents, memo))

    # --- processing ---
    balance = _parse_opening(opening)
    # Treat "-0.00" as zero
    if balance == 0:
        balance = 0

    applied = []  # (date_str, kind, amount_cents, memo, balance_after)
    od_fee_dates = set()  # dates that already got an automatic overdraft fee

    for d_str, d_obj, kind, amt, memo in validated:
        if kind == 'credit':
            balance += amt
        else:
            balance -= amt
        applied.append((d_str, kind, amt, memo, balance))

        # automatic overdraft fee after a debit that leaves balance strictly negative
        if kind == 'debit' and balance < 0 and d_str not in od_fee_dates:
            od_fee_dates.add(d_str)
            fee_amt = 2500  # 25.00
            balance -= fee_amt
            applied.append((d_str, 'fee', fee_amt, 'OVERDRAFT FEE', balance))

    # --- rendering ---
    lines = []
    lines.append('Opening balance: ' + _money(_parse_opening(opening) if _parse_opening(opening) != 0 else 0))

    # Re-parse opening for display consistency (already handled -0.00)
    open_cents = _parse_opening(opening)
    if open_cents == 0:
        open_cents = 0
    lines[0] = 'Opening balance: ' + _money(open_cents)

    n_credit = n_debit = n_fee = 0
    for d_str, kind, amt, memo, bal in applied:
        memo_col = _normalize_memo(memo)
        if kind == 'credit':
            sign = '+'
            n_credit += 1
        else:
            sign = '-'
            if kind == 'debit':
                n_debit += 1
            else:
                n_fee += 1
        amt_col = (sign + _money(amt)).rjust(14)
        bal_col = _money(bal).rjust(15)
        flag = ' OD' if bal < 0 else ''
        lines.append(f'{d_str}  {memo_col}  {amt_col}  {bal_col}{flag}')

    final = applied[-1][4] if applied else open_cents
    if final == 0:
        final = 0
    lines.append('Closing balance: ' + _money(final))
    lines.append(f'Credits: {n_credit}  Debits: {n_debit}  Fees: {n_fee}')
    return lines

from __future__ import annotations

import re
from typing import Optional


def pick_version(available, constraint) -> str | None:
    # --- version parsing / ordering ---
    _VERSION_RE = re.compile(
        r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:~rc([1-9]\d*))?$"
    )

    def parse_version(s: str):
        m = _VERSION_RE.fullmatch(s)
        if not m:
            return None
        x, y, z = int(m.group(1)), int(m.group(2)), int(m.group(3))
        rc = m.group(4)
        # plain release sorts above any rc: use rc_num = infinity for plain
        if rc is None:
            rc_key = (1, 0)  # (is_release, n)
        else:
            rc_key = (0, int(rc))
        return (x, y, z, rc_key)

    def version_key(s: str):
        p = parse_version(s)
        assert p is not None
        return p

    # --- validation of available ---
    if not isinstance(available, list):
        raise TypeError("available must be a list")
    parsed_available = []
    for i, element in enumerate(available):
        if not isinstance(element, str) or parse_version(element) is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed_available.append(element)

    # --- validation of constraint ---
    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")
    if constraint == "" or constraint.strip(" ") == "":
        # "consists only of spaces" — only ASCII space, per spec (" " only)
        # empty or only spaces
        if constraint == "" or all(c == " " for c in constraint):
            raise ValueError("empty constraint")
        # if other whitespace only, still empty-ish? Spec says "empty or consists only of spaces"
        # So tabs-only would NOT hit this and fall through — treat as non-empty string with alternatives
        if constraint.strip() == "" and all(c == " " for c in constraint):
            raise ValueError("empty constraint")
    # Re-check strictly: empty or only " " characters
    if len(constraint) == 0 or (constraint.replace(" ", "") == "" and all(c == " " for c in constraint)):
        raise ValueError("empty constraint")

    # Actually simpler:
    if constraint == "" or set(constraint) <= {" "}:
        raise ValueError("empty constraint")

    _PART_RE = re.compile(r"^(0|[1-9]\d*)$")

    def is_valid_version_str(s: str) -> bool:
        return parse_version(s) is not None

    def is_valid_part(s: str) -> bool:
        return bool(_PART_RE.fullmatch(s))

    def parse_clause(clause: str):
        """Return a matcher callable or None if invalid.
        Matcher: (version_str, parsed_tuple) -> bool
        """
        if clause == "*":
            return lambda v, p: True

        # X.Y.* or X.*
        if clause.endswith(".*"):
            body = clause[:-2]
            parts = body.split(".")
            if len(parts) == 1:
                if not is_valid_part(parts[0]):
                    return None
                x = int(parts[0])
                return lambda v, p, x=x: p[0] == x
            if len(parts) == 2:
                if not is_valid_part(parts[0]) or not is_valid_part(parts[1]):
                    return None
                x, y = int(parts[0]), int(parts[1])
                return lambda v, p, x=x, y=y: p[0] == x and p[1] == y
            return None

        # @X.Y
        if clause.startswith("@"):
            body = clause[1:]
            parts = body.split(".")
            if len(parts) != 2:
                return None
            if not is_valid_part(parts[0]) or not is_valid_part(parts[1]):
                return None
            x, y = int(parts[0]), int(parts[1])
            return lambda v, p, x=x, y=y: p[0] == x and p[1] >= y

        # operators
        for op in ("!=", ">=", "<=", ">", "<", "="):
            if clause.startswith(op):
                ver = clause[len(op) :]
                if not is_valid_version_str(ver):
                    return None
                # no inner spaces etc. — version re already rejects spaces
                vp = parse_version(ver)
                if op == "=":
                    return lambda v, p, vp=vp: p == vp
                if op == "!=":
                    return lambda v, p, vp=vp: p != vp
                if op == ">":
                    return lambda v, p, vp=vp: p > vp
                if op == ">=":
                    return lambda v, p, vp=vp: p >= vp
                if op == "<":
                    return lambda v, p, vp=vp: p < vp
                if op == "<=":
                    return lambda v, p, vp=vp: p <= vp

        # bare V
        if is_valid_version_str(clause):
            vp = parse_version(clause)
            return lambda v, p, vp=vp: p == vp

        return None

    # Split alternatives on "|"
    raw_alternatives = constraint.split("|")
    compiled_alternatives = []  # list of (allow_rc: bool, matchers: list)

    for a_idx, raw_alt in enumerate(raw_alternatives, start=1):
        alt = raw_alt
        # remove spaces at both ends (" " only)
        alt = alt.strip(" ")
        allow_rc = False
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")
        if alt == "":
            raise ValueError(f"alternative {a_idx} is empty")

        raw_clauses = alt.split(",")
        matchers = []
        for c_idx, raw_clause in enumerate(raw_clauses, start=1):
            clause = raw_clause.strip(" ")
            matcher = parse_clause(clause)
            if matcher is None:
                raise ValueError(
                    f"alternative {a_idx}, clause {c_idx}: invalid clause {clause!r}"
                )
            matchers.append(matcher)
        compiled_alternatives.append((allow_rc, matchers))

    def is_rc(parsed) -> bool:
        return parsed[3][0] == 0  # (is_release, n) — is_release==0 means rc

    def satisfies(version_str: str) -> bool:
        p = parse_version(version_str)
        for allow_rc, matchers in compiled_alternatives:
            if is_rc(p) and not allow_rc:
                continue
            if all(m(version_str, p) for m in matchers):
                return True
        return False

    best = None
    best_key = None
    for v in parsed_available:
        if satisfies(v):
            k = version_key(v)
            if best_key is None or k > best_key:
                best_key = k
                best = v
    return best

def parse_outline(text: str) -> tuple:
    lines = text.split("\n")
    n = len(lines)

    # Stack of open blocks: each is
    #   {"indent": int, "kind": "map"|"list", "value": dict|list, "opener": bool}
    # opener means the last added entry is waiting for a nested block (or None).
    stack = []
    root = None
    prev_was_opener = False
    prev_indent = -1

    def convert_scalar(s, line_no):
        if s.startswith('"'):
            i = 1
            out = []
            while i < len(s):
                c = s[i]
                if c == "\\":
                    if i + 1 >= len(s):
                        return ("error", line_no, "bad escape")
                    nxt = s[i + 1]
                    if nxt == "\\":
                        out.append("\\")
                    elif nxt == '"':
                        out.append('"')
                    elif nxt == "n":
                        out.append("\n")
                    elif nxt == "t":
                        out.append("\t")
                    else:
                        return ("error", line_no, "bad escape")
                    i += 2
                elif c == '"':
                    if i != len(s) - 1:
                        return ("error", line_no, "bad string")
                    return ("ok", "".join(out))
                else:
                    out.append(c)
                    i += 1
            return ("error", line_no, "bad string")
        if s == "true":
            return ("ok", True)
        if s == "false":
            return ("ok", False)
        if s == "null":
            return ("ok", None)
        # integer: -?(0|[1-9][0-9]*)
        if s and (s[0] == "-" or s[0].isdigit()):
            t = s[1:] if s[0] == "-" else s
            if t == "0" or (t and t[0] in "123456789" and t.isdigit()):
                # reject leading zeros like 007; "-0" -> 0
                if t == "0" or not t.startswith("0"):
                    val = int(s)
                    return ("ok", val)
        return ("ok", s)

    def is_valid_key(k):
        if not k:
            return False
        c0 = k[0]
        if not (("A" <= c0 <= "Z") or ("a" <= c0 <= "z") or c0 == "_"):
            return False
        for c in k[1:]:
            if not (
                ("A" <= c <= "Z")
                or ("a" <= c <= "z")
                or ("0" <= c <= "9")
                or c == "_"
                or c == "-"
            ):
                return False
        return True

    for line_idx, line in enumerate(lines):
        line_no = line_idx + 1

        # LEAD / REST
        i = 0
        while i < len(line) and line[i] in (" ", "\t"):
            i += 1
        lead = line[:i]
        rest = line[i:]

        # blank
        if rest == "":
            continue
        # comment
        if rest.startswith("#"):
            continue

        # CONTENT line
        # 1. tab in indentation
        if "\t" in lead:
            return ("error", line_no, "tab in indentation")

        indent = len(lead)

        # 2/3. ITEM or KEY
        kind = None  # "item" or "key"
        is_opener = False
        key = None
        text = None  # scalar text or None for opener

        if rest == "-" or rest.startswith("- "):
            kind = "item"
            if rest == "-":
                text_raw = ""
            else:
                text_raw = rest[2:]
            # strip spaces only from both ends
            text_raw = text_raw.strip(" ")
            if text_raw == "":
                is_opener = True
                text = None
            else:
                is_opener = False
                text = text_raw
        else:
            # KEY line
            colon = rest.find(":")
            if colon < 0:
                return ("error", line_no, "invalid entry")
            key_part = rest[:colon]
            if not is_valid_key(key_part):
                return ("error", line_no, "invalid entry")
            after = rest[colon + 1 :]
            # AFTER only spaces -> KEY OPENER
            if after.strip(" ") == "" and (after == "" or all(c == " " for c in after)):
                # "consists only of spaces (or is empty)"
                is_opener = True
                text = None
                kind = "key"
                key = key_part
            else:
                if not after.startswith(" "):
                    return ("error", line_no, "invalid entry")
                text_raw = after.strip(" ")
                is_opener = False
                text = text_raw
                kind = "key"
                key = key_part

        # 4. scalar conversion
        value = None
        if not is_opener:
            conv = convert_scalar(text, line_no)
            if conv[0] == "error":
                return conv
            value = conv[1]

        # STRUCTURE
        block_kind = "map" if kind == "key" else "list"

        if root is None:
            # first content line
            if indent != 0:
                return ("error", line_no, "unexpected indent")
            if block_kind == "map":
                root = {}
            else:
                root = []
            stack = [{"indent": 0, "kind": block_kind, "value": root}]
            if is_opener:
                # add placeholder
                if block_kind == "map":
                    root[key] = None
                    stack[-1]["pending_key"] = key
                else:
                    root.append(None)
                    stack[-1]["pending_idx"] = 0
                prev_was_opener = True
                prev_indent = indent
            else:
                if block_kind == "map":
                    root[key] = value
                else:
                    root.append(value)
                prev_was_opener = False
                prev_indent = indent
            continue

        # Not first line
        if prev_was_opener and indent > prev_indent:
            # start NEW nested block as opener's value
            if block_kind == "map":
                new_val = {}
            else:
                new_val = []
            # attach to opener
            parent = stack[-1]
            if parent["kind"] == "map":
                pk = parent["pending_key"]
                parent["value"][pk] = new_val
                del parent["pending_key"]
            else:
                pi = parent["pending_idx"]
                parent["value"][pi] = new_val
                del parent["pending_idx"]
            stack.append({"indent": indent, "kind": block_kind, "value": new_val})
            if is_opener:
                if block_kind == "map":
                    new_val[key] = None
                    stack[-1]["pending_key"] = key
                else:
                    new_val.append(None)
                    stack[-1]["pending_idx"] = 0
                prev_was_opener = True
                prev_indent = indent
            else:
                if block_kind == "map":
                    new_val[key] = value
                else:
                    new_val.append(value)
                prev_was_opener = False
                prev_indent = indent
            continue

        # Otherwise: continue an open block (opener keeps None if any)
        # Clear pending opener without nested block — already None
        if prev_was_opener:
            parent = stack[-1]
            if "pending_key" in parent:
                del parent["pending_key"]
            if "pending_idx" in parent:
                del parent["pending_idx"]
            prev_was_opener = False

        # Close deeper blocks if needed
        if indent > stack[-1]["indent"]:
            return ("error", line_no, "unexpected indent")

        while stack and stack[-1]["indent"] > indent:
            stack.pop()

        if not stack or stack[-1]["indent"] != indent:
            return ("error", line_no, "inconsistent dedent")

        cur = stack[-1]
        if cur["kind"] != block_kind:
            return ("error", line_no, "mixed block")

        if block_kind == "map":
            if key in cur["value"]:
                return ("error", line_no, f"duplicate key '{key}'")
            if is_opener:
                cur["value"][key] = None
                cur["pending_key"] = key
                prev_was_opener = True
                prev_indent = indent
            else:
                cur["value"][key] = value
                prev_was_opener = False
                prev_indent = indent
        else:
            if is_opener:
                cur["value"].append(None)
                cur["pending_idx"] = len(cur["value"]) - 1
                prev_was_opener = True
                prev_indent = indent
            else:
                cur["value"].append(value)
                prev_was_opener = False
                prev_indent = indent

    # end of document: openers already have None
    if root is None:
        return ("ok", None)
    return ("ok", root)

from __future__ import annotations

from typing import Any, Dict, List, Optional, Tuple

def run_pile(src: str, max_steps: int) -> tuple:
    # -------------------- tokenize --------------------
    tokens: List[str] = []
    i, n = 0, len(src)
    WS = " \t\n\r"
    while i < n:
        c = src[i]
        if c in WS:
            i += 1
            continue
        if c == "[" or c == "]":
            tokens.append(c)
            i += 1
            continue
        j = i + 1
        while j < n and src[j] not in WS and src[j] != "[" and src[j] != "]":
            j += 1
        tokens.append(src[i:j])
        i = j

    T = tokens
    N = len(T)

    def is_int_tok(t: str) -> bool:
        if not t:
            return False
        if t[0] == "-":
            s = t[1:]
        else:
            s = t
        return bool(s) and s.isdigit()  # ASCII digits only via str.isdigit on pure digits

    # str.isdigit() is True for some Unicode digits; restrict to ASCII:
    def is_int_tok(t: str) -> bool:
        if not t:
            return False
        start = 1 if t[0] == "-" else 0
        if start >= len(t):
            return False
        for ch in t[start:]:
            if ch < "0" or ch > "9":
                return False
        return True

    def parse_int(t: str) -> int:
        return int(t)

    BUILTINS = frozenset({
        "dup", "drop", "swap", "over", "rot",
        "+", "-", "*", "/", "%", "<", "=",
        "if", "times", "while", "call", "dip",
    })

    # -------------------- structure check + build elements --------------------
    # Element kinds:
    #   ("I", idx, int_value)
    #   ("W", idx, name)
    #   ("Q", idx, body)      body = list of elements
    #   ("D", idx, name, body)

    top: List = []
    # open frames: [kind, idx, body, name|None]
    # kind 0 = quote, 1 = def
    open_st: List = []

    k = 0
    err: Optional[Tuple[int, str]] = None
    while k < N:
        t = T[k]
        if t == "[":
            open_st.append([0, k, [], None])
            k += 1
        elif t == "]":
            if not open_st or open_st[-1][0] != 0:
                err = (k, "unmatched ]")
                break
            fr = open_st.pop()
            elem = ("Q", fr[1], fr[2])
            if open_st:
                open_st[-1][2].append(elem)
            else:
                top.append(elem)
            k += 1
        elif t == ":":
            if open_st:
                err = (k, "misplaced :")
                break
            if k + 1 >= N:
                err = (k, "unclosed :")
                break
            name_idx = k + 1
            name = T[name_idx]
            if (
                name in ("[", "]", ":", ";")
                or is_int_tok(name)
                or name in BUILTINS
            ):
                err = (name_idx, "bad name")
                break
            open_st.append([1, k, [], name])
            k = name_idx + 1
        elif t == ";":
            if not open_st or open_st[-1][0] != 1:
                err = (k, "unmatched ;")
                break
            fr = open_st.pop()
            top.append(("D", fr[1], fr[3], fr[2]))
            k += 1
        else:
            if is_int_tok(t):
                elem = ("I", k, parse_int(t))
            else:
                elem = ("W", k, t)
            if open_st:
                open_st[-1][2].append(elem)
            else:
                top.append(elem)
            k += 1

    if err is None and open_st:
        earliest = min(open_st, key=lambda f: f[1])
        if earliest[0] == 0:
            err = (earliest[1], "unclosed [")
        else:
            err = (earliest[1], "unclosed :")

    if err is not None:
        return ("error", err[0], err[1])

    # -------------------- execution (iterative) --------------------
    # Value: int | list (quotation display form is built lazily from body)
    # We store quotations as ("Q", body_elements) on the stack.

    stack: List[Any] = []
    defs: Dict[str, List] = {}

    # Work item:
    #   ("E", elem)           — execute one element (consumes a step)
    #   ("S", seq, ip)        — continue sequence at index ip (no step by itself)
    # For times/while we use specialized frames:
    #   ("T", body, left)     — times remaining
    #   ("WH", cbody, bbody, phase)  phase 0 = run cond, 1 = check tos
    #   ("DIP", val)          — push val back after body

    # To avoid huge Python lists of work items for long sequences, we use
    # sequence frames with instruction pointers.

    work: List[Any] = [("S", top, 0)]
    steps = 0

    def q_display(body: List) -> List:
        out: List[Any] = []
        for e in body:
            kind = e[0]
            if kind == "I":
                out.append(T[e[1]])
            elif kind == "W":
                out.append(e[2])
            elif kind == "Q":
                out.append(q_display(e[2]))
            else:
                # should not appear inside quotes
                out.append("?")
        return out

    def underflow(idx: int) -> Tuple:
        return ("error", idx, "stack underflow")

    def type_error(idx: int) -> Tuple:
        return ("error", idx, "type error")

    while work:
        item = work.pop()
        tag = item[0]

        if tag == "S":
            seq = item[1]
            ip = item[2]
            if ip >= len(seq):
                continue
            # push continuation then element
            if ip + 1 < len(seq):
                work.append(("S", seq, ip + 1))
            work.append(("E", seq[ip]))
            continue

        if tag == "T":
            # ("T", body, left)
            body = item[1]
            left = item[2]
            if left <= 0:
                continue
            if left > 1:
                work.append(("T", body, left - 1))
            if body:
                work.append(("S", body, 0))
            # empty body: nothing to run, no steps
            continue

        if tag == "WH":
            # ("WH", cbody, bbody) — after cond ran; check value
            cbody, bbody = item[1], item[2]
            idx = item[3]
            if len(stack) < 1:
                return underflow(idx)
            v = stack.pop()
            if type(v) is not int:
                return type_error(idx)
            if v != 0:
                # run body then cond again then check
                work.append(("WH", cbody, bbody, idx))
                work.append(("S", cbody, 0))
                if bbody:
                    work.append(("S", bbody, 0))
            continue

        if tag == "WHi":
            # initiate while: run cond first then WH check
            cbody, bbody, idx = item[1], item[2], item[3]
            work.append(("WH", cbody, bbody, idx))
            work.append(("S", cbody, 0))
            continue

        if tag == "DIP":
            stack.append(item[1])
            continue

        if tag == "E":
            elem = item[1]
            kind = elem[0]
            idx = elem[1]

            steps += 1
            if steps > max_steps:
                return ("error", idx, "step limit exceeded")

            if kind == "I":
                stack.append(elem[2])
                continue

            if kind == "Q":
                stack.append(("Q", elem[2]))
                continue

            if kind == "D":
                defs[elem[2]] = elem[3]
                continue

            # word
            name = elem[2]

            # builtins
            if name == "dup":
                if len(stack) < 1:
                    return underflow(idx)
                stack.append(stack[-1])
            elif name == "drop":
                if len(stack) < 1:
                    return underflow(idx)
                stack.pop()
            elif name == "swap":
                if len(stack) < 2:
                    return underflow(idx)
                stack[-1], stack[-2] = stack[-2], stack[-1]
            elif name == "over":
                if len(stack) < 2:
                    return underflow(idx)
                stack.append(stack[-2])
            elif name == "rot":
                if len(stack) < 3:
                    return underflow(idx)
                a = stack[-3]
                stack[-3] = stack[-2]
                stack[-2] = stack[-1]
                stack[-1] = a
            elif name == "+" or name == "-" or name == "*" or name == "/" or name == "%" or name == "<" or name == "=":
                if len(stack) < 2:
                    return underflow(idx)
                b = stack.pop()
                a = stack.pop()
                if type(a) is not int or type(b) is not int:
                    return type_error(idx)
                if name == "+":
                    stack.append(a + b)
                elif name == "-":
                    stack.append(a - b)
                elif name == "*":
                    stack.append(a * b)
                elif name == "/":
                    if b == 0:
                        return ("error", idx, "division by zero")
                    stack.append(a // b)
                elif name == "%":
                    if b == 0:
                        return ("error", idx, "division by zero")
                    stack.append(a % b)
                elif name == "<":
                    stack.append(1 if a < b else 0)
                else:  # "="
                    stack.append(1 if a == b else 0)
            elif name == "if":
                if len(stack) < 3:
                    return underflow(idx)
                f = stack.pop()
                t = stack.pop()
                c = stack.pop()
                if type(c) is not int:
                    return type_error(idx)
                if not (isinstance(t, tuple) and t[0] == "Q"):
                    return type_error(idx)
                if not (isinstance(f, tuple) and f[0] == "Q"):
                    return type_error(idx)
                body = t[1] if c != 0 else f[1]
                if body:
                    work.append(("S", body, 0))
            elif name == "times":
                if len(stack) < 2:
                    return underflow(idx)
                nval = stack.pop()
                q = stack.pop()
                if not (isinstance(q, tuple) and q[0] == "Q"):
                    return type_error(idx)
                if type(nval) is not int:
                    return type_error(idx)
                if nval < 0:
                    return ("error", idx, "negative count")
                body = q[1]
                if nval > 0 and body:
                    work.append(("T", body, nval))
                # empty body or nval==0: done, no steps for empty
            elif name == "while":
                if len(stack) < 2:
                    return underflow(idx)
                b = stack.pop()
                c = stack.pop()
                if not (isinstance(c, tuple) and c[0] == "Q"):
                    return type_error(idx)
                if not (isinstance(b, tuple) and b[0] == "Q"):
                    return type_error(idx)
                work.append(("WHi", c[1], b[1], idx))
            elif name == "call":
                if len(stack) < 1:
                    return underflow(idx)
                q = stack.pop()
                if not (isinstance(q, tuple) and q[0] == "Q"):
                    return type_error(idx)
                if q[1]:
                    work.append(("S", q[1], 0))
            elif name == "dip":
                if len(stack) < 2:
                    return underflow(idx)
                q = stack.pop()
                a = stack.pop()
                if not (isinstance(q, tuple) and q[0] == "Q"):
                    return type_error(idx)
                work.append(("DIP", a))
                if q[1]:
                    work.append(("S", q[1], 0))
            elif name in defs:
                body = defs[name]
                if body:
                    work.append(("S", body, 0))
            else:
                # could be builtin we missed — already handled; unknown
                if name in BUILTINS:
                    # should not happen
                    return ("error", idx, f"unknown word '{name}'")
                return ("error", idx, f"unknown word '{name}'")
            continue

        # unknown work tag
        return ("error", 0, "internal")

    # format stack
    out_stack: List[Any] = []
    for v in stack:
        if type(v) is int:
            out_stack.append(v)
        elif isinstance(v, tuple) and v[0] == "Q":
            out_stack.append(q_display(v[1]))
        else:
            out_stack.append(v)
    return ("ok", out_stack)

import sys
from typing import Any, Union

sys.setrecursionlimit(4000)

# Token kinds
END = "END"
LPAREN, RPAREN, LBRACK, RBRACK, COMMA = "(", ")", "[", "]", ","
NE, LE, GE, EQ, LT, GT = "!=", "<=", ">=", "=", "<", ">"
INT, STRING, WORD = "INT", "STRING", "WORD"
AND, OR, NOT, IN, HAS = "and", "or", "not", "in", "has"
KEYWORDS = {AND, OR, NOT, IN, HAS}


class LexError(Exception):
    def __init__(self, pos: int, message: str):
        self.pos = pos
        self.message = message


class ParseError(Exception):
    def __init__(self, pos: int, message: str):
        self.pos = pos
        self.message = message


class Token:
    __slots__ = ("kind", "value", "pos", "text")

    def __init__(self, kind: str, value: Any, pos: int, text: str):
        self.kind = kind
        self.value = value
        self.pos = pos
        self.text = text


def tokenize(query: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(query)

    while i < n:
        c = query[i]

        # Whitespace
        if c in " \t\n":
            i += 1
            continue

        # Punctuation
        if c in "()[],":
            tokens.append(Token(c, c, i, c))
            i += 1
            continue

        # Two-char comparison operators
        if i + 1 < n:
            two = query[i : i + 2]
            if two in ("!=", "<=", ">="):
                tokens.append(Token(two, two, i, two))
                i += 2
                continue

        # One-char comparison operators
        if c in "=<>":
            tokens.append(Token(c, c, i, c))
            i += 1
            continue

        # INT: optional '-' followed by digits
        if c == "-" or c.isdigit():
            start = i
            if c == "-":
                if i + 1 >= n or not query[i + 1].isdigit():
                    raise LexError(i, f"unexpected character '-'")
                i += 1
            if i >= n or not query[i].isdigit():
                raise LexError(start, f"unexpected character '-'")
            while i < n and query[i].isdigit():
                i += 1
            text = query[start:i]
            tokens.append(Token(INT, int(text), start, text))
            continue

        # STRING
        if c == '"':
            start = i
            i += 1
            chars: list[str] = []
            while i < n:
                ch = query[i]
                if ch == "\\":
                    if i + 1 >= n:
                        raise LexError(i, "bad escape")
                    nxt = query[i + 1]
                    if nxt == '"':
                        chars.append('"')
                    elif nxt == "\\":
                        chars.append("\\")
                    else:
                        raise LexError(i, "bad escape")
                    i += 2
                    continue
                if ch == '"':
                    i += 1
                    text = query[start:i]
                    tokens.append(Token(STRING, "".join(chars), start, text))
                    break
                chars.append(ch)
                i += 1
            else:
                raise LexError(start, "unterminated string")
            continue

        # WORD / keyword
        if c.isalpha() or c == "_":
            start = i
            i += 1
            while i < n and (query[i].isalnum() or query[i] in "_."):
                i += 1
            text = query[start:i]
            if text in KEYWORDS:
                tokens.append(Token(text, text, start, text))
            else:
                tokens.append(Token(WORD, text, start, text))
            continue

        # Unexpected character
        raise LexError(i, f"unexpected character '{c}'")

    tokens.append(Token(END, None, n, ""))
    return tokens


# AST node types
# ("cmp", field, op, literal)
# ("in", field, list_of_literals)
# ("has", field)
# ("not", expr)
# ("and", left, right)
# ("or", left, right)


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def error(self, tok: Token) -> ParseError:
        if tok.kind == END:
            return ParseError(tok.pos, "unexpected end of input")
        return ParseError(tok.pos, f"unexpected token '{tok.text}'")

    def expect(self, kind: str) -> Token:
        tok = self.current()
        if tok.kind != kind:
            raise self.error(tok)
        return self.advance()

    def parse(self):
        expr = self.parse_or()
        if self.current().kind != END:
            raise self.error(self.current())
        return expr

    def parse_or(self):
        left = self.parse_and()
        while self.current().kind == OR:
            self.advance()
            right = self.parse_and()
            left = ("or", left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.current().kind == AND:
            self.advance()
            right = self.parse_not()
            left = ("and", left, right)
        return left

    def parse_not(self):
        if self.current().kind == NOT:
            self.advance()
            operand = self.parse_not()
            return ("not", operand)
        return self.parse_primary()

    def parse_primary(self):
        tok = self.current()

        if tok.kind == LPAREN:
            self.advance()
            expr = self.parse_or()
            self.expect(RPAREN)
            return expr

        if tok.kind == HAS:
            self.advance()
            field_tok = self.current()
            if field_tok.kind != WORD:
                raise self.error(field_tok)
            self.advance()
            return ("has", field_tok.value)

        if tok.kind == WORD:
            field = tok.value
            self.advance()
            op_tok = self.current()

            if op_tok.kind in (EQ, NE, LT, LE, GT, GE):
                op = op_tok.kind
                self.advance()
                lit = self.parse_literal()
                return ("cmp", field, op, lit)

            if op_tok.kind == IN:
                self.advance()
                self.expect(LBRACK)
                literals = [self.parse_literal()]
                while self.current().kind == COMMA:
                    self.advance()
                    literals.append(self.parse_literal())
                self.expect(RBRACK)
                return ("in", field, literals)

            raise self.error(op_tok)

        raise self.error(tok)

    def parse_literal(self):
        tok = self.current()
        if tok.kind == INT:
            self.advance()
            return tok.value
        if tok.kind == STRING:
            self.advance()
            return tok.value
        raise self.error(tok)


# Three-valued logic: True, False, None (UNKNOWN)

def eval_expr(expr, record: dict) -> Union[bool, None]:
    kind = expr[0]

    if kind == "cmp":
        _, field, op, literal = expr
        if field not in record:
            return None
        val = record[field]
        # Different types
        if type(val) is not type(literal):
            if op == EQ:
                return False
            if op == NE:
                return True
            return None  # < <= > >=
        # Same type
        if op == EQ:
            return val == literal
        if op == NE:
            return val != literal
        if op == LT:
            return val < literal
        if op == LE:
            return val <= literal
        if op == GT:
            return val > literal
        if op == GE:
            return val >= literal

    if kind == "in":
        _, field, literals = expr
        if field not in record:
            return None
        val = record[field]
        for lit in literals:
            if type(val) is type(lit) and val == lit:
                return True
        return False

    if kind == "has":
        _, field = expr
        return field in record

    if kind == "not":
        v = eval_expr(expr[1], record)
        if v is None:
            return None
        return not v

    if kind == "and":
        # FALSE if any FALSE, else UNKNOWN if any UNKNOWN, else TRUE
        # Evaluate both (or short-circuit carefully)
        left = eval_expr(expr[1], record)
        if left is False:
            return False
        right = eval_expr(expr[2], record)
        if right is False:
            return False
        if left is None or right is None:
            return None
        return True

    if kind == "or":
        # TRUE if any TRUE, else UNKNOWN if any UNKNOWN, else FALSE
        left = eval_expr(expr[1], record)
        if left is True:
            return True
        right = eval_expr(expr[2], record)
        if right is True:
            return True
        if left is None or right is None:
            return None
        return False

    raise RuntimeError(f"unknown expr kind: {kind}")


def filter_records(query: str, records: list[dict]) -> tuple:
    try:
        tokens = tokenize(query)
    except LexError as e:
        return ("error", e.pos, e.message)

    try:
        parser = Parser(tokens)
        ast = parser.parse()
    except ParseError as e:
        return ("error", e.pos, e.message)

    indices = []
    for i, rec in enumerate(records):
        result = eval_expr(ast, rec)
        if result is True:
            indices.append(i)

    return ("ok", indices)

import sys
import threading

def evaluate(src: str, env: dict) -> tuple:
    """Parse and evaluate one Tally expression."""
    # Deep nesting (parens / power / unary) can exceed the default C stack.
    # Run the real work on a thread with a large stack.
    out = []

    def _run():
        out.append(_evaluate_impl(src, env))

    prev = threading.stack_size(32 * 1024 * 1024)
    try:
        sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))
        t = threading.Thread(target=_run)
        t.start()
        t.join()
    finally:
        threading.stack_size(prev)

    return out[0]


# ---------------------------------------------------------------------------
# Tokenization
# ---------------------------------------------------------------------------

# token kinds
INT, NAME, OP, INVALID, END = "INT", "NAME", "OP", "INVALID", "END"

_TWO_CHAR = {"<=": 1, ">=": 1, "==": 1, "!=": 1}
_ONE_CHAR = set("+-*/%^():?<>")


def _tokenize(src: str):
    """Return list of (start_pos, kind, text). text is str for all kinds."""
    tokens = []
    n = len(src)
    i = 0
    while i < n:
        c = src[i]
        if c == " ":
            i += 1
            continue
        start = i
        if c.isdigit():
            i += 1
            while i < n and src[i].isdigit():
                i += 1
            tokens.append((start, INT, src[start:i]))
            continue
        if c == "_" or ("a" <= c <= "z"):
            i += 1
            while i < n and (src[i] == "_" or "a" <= src[i] <= "z" or src[i].isdigit()):
                i += 1
            tokens.append((start, NAME, src[start:i]))
            continue
        if i + 1 < n and src[i : i + 2] in _TWO_CHAR:
            tokens.append((start, OP, src[i : i + 2]))
            i += 2
            continue
        if c in _ONE_CHAR:
            tokens.append((start, OP, c))
            i += 1
            continue
        # invalid character
        tokens.append((start, INVALID, c))
        i += 1
    tokens.append((n, END, ""))
    return tokens


# ---------------------------------------------------------------------------
# AST nodes (tuples for lightness)
# ---------------------------------------------------------------------------
# ("int", pos, value)
# ("name", pos, name)
# ("neg", pos, expr)          pos = position of '-'
# ("bin", pos, op, left, right)  pos = operator position
# ("cmp", pos, op, left, right)
# ("tern", pos_q, cond, a, b)    pos_q = position of '?'


# ---------------------------------------------------------------------------
# Parser (recursive descent; deep recursion OK via large thread stack)
# ---------------------------------------------------------------------------

class _ParseError(Exception):
    def __init__(self, pos, message):
        self.pos = pos
        self.message = message


class _Parser:
    __slots__ = ("tokens", "i")

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def _cur(self):
        return self.tokens[self.i]

    def _advance(self):
        self.i += 1

    def _fail_cur(self):
        pos, kind, text = self._cur()
        if kind == END:
            raise _ParseError(pos, "unexpected end of input")
        if kind == INVALID:
            raise _ParseError(pos, f"unexpected character '{text}'")
        raise _ParseError(pos, f"unexpected token '{text}'")

    def parse_expr(self):
        node = self.parse_cond()
        pos, kind, text = self._cur()
        if kind != END:
            self._fail_cur()
        return node

    def parse_cond(self):
        # cond := cmp [ '?' cond ':' cond ]   right-associative
        left = self.parse_cmp()
        pos, kind, text = self._cur()
        if kind == OP and text == "?":
            qpos = pos
            self._advance()
            mid = self.parse_cond()
            pos2, kind2, text2 = self._cur()
            if not (kind2 == OP and text2 == ":"):
                self._fail_cur()
            self._advance()
            right = self.parse_cond()
            return ("tern", qpos, left, mid, right)
        return left

    def parse_cmp(self):
        # cmp := sum [ cmpop sum ]   non-associative
        left = self.parse_sum()
        pos, kind, text = self._cur()
        if kind == OP and text in ("<", "<=", ">", ">=", "==", "!="):
            op = text
            oppos = pos
            self._advance()
            right = self.parse_sum()
            # another cmpop would be invalid — detected when higher levels
            # see leftover tokens, or here if we peek
            pos2, kind2, text2 = self._cur()
            if kind2 == OP and text2 in ("<", "<=", ">", ">=", "==", "!="):
                # a < b < c  → error at second '<'
                self._fail_cur()
            return ("cmp", oppos, op, left, right)
        return left

    def parse_sum(self):
        left = self.parse_term()
        while True:
            pos, kind, text = self._cur()
            if kind == OP and text in ("+", "-"):
                op = text
                oppos = pos
                self._advance()
                right = self.parse_term()
                left = ("bin", oppos, op, left, right)
            else:
                break
        return left

    def parse_term(self):
        left = self.parse_unary()
        while True:
            pos, kind, text = self._cur()
            if kind == OP and text in ("*", "/", "%"):
                op = text
                oppos = pos
                self._advance()
                right = self.parse_unary()
                left = ("bin", oppos, op, left, right)
            else:
                break
        return left

    def parse_unary(self):
        # unary := '-' unary | power
        # iterative for long minus chains
        minuses = []
        while True:
            pos, kind, text = self._cur()
            if kind == OP and text == "-":
                minuses.append(pos)
                self._advance()
            else:
                break
        node = self.parse_power()
        for pos in reversed(minuses):
            node = ("neg", pos, node)
        return node

    def parse_power(self):
        # power := atom [ '^' unary ]   right-associative
        # collect a chain atom (^ unary)* and fold right
        base = self.parse_atom()
        pos, kind, text = self._cur()
        if kind == OP and text == "^":
            oppos = pos
            self._advance()
            # exponent is unary (so may start with '-')
            exp = self.parse_unary()
            return ("bin", oppos, "^", base, exp)
        return base

    def parse_atom(self):
        pos, kind, text = self._cur()
        if kind == INT:
            self._advance()
            return ("int", pos, int(text))
        if kind == NAME:
            self._advance()
            return ("name", pos, text)
        if kind == OP and text == "(":
            self._advance()
            node = self.parse_cond()
            pos2, kind2, text2 = self._cur()
            if not (kind2 == OP and text2 == ")"):
                self._fail_cur()
            self._advance()
            return node
        self._fail_cur()


# ---------------------------------------------------------------------------
# Evaluation (iterative where it matters; recursion OK on large stack thread)
# Ternary short-circuit requires careful branching — use explicit stack.
# ---------------------------------------------------------------------------

class _EvalError(Exception):
    def __init__(self, pos, message):
        self.pos = pos
        self.message = message


def _eval_ast(node, env):
    """
    Iterative AST evaluator with short-circuit ternary.
    Stack frames:
      ("eval", node)           — evaluate node, push value
      ("neg", pos)             — pop v, push -v
      ("bin", pos, op)         — pop rhs, lhs; push lhs op rhs
      ("cmp", pos, op)         — pop rhs, lhs; push 0/1
      ("tern_decide", a, b)    — pop cond; push eval of a or b
      ("value", v)             — already a value (used internally)
    Values are left on a value stack.
    """
    # For simplicity and correctness with short-circuit, a recursive evaluator
    # is clearest; we already run on a large-stack thread. Power/unary/paren
    # depth is bounded by the same 30k, so recursion here is fine.
    return _eval_rec(node, env)


def _eval_rec(node, env):
    tag = node[0]

    if tag == "int":
        return node[2]

    if tag == "name":
        _, pos, name = node
        if name not in env:
            raise _EvalError(pos, f"unknown name '{name}'")
        return env[name]

    if tag == "neg":
        _, pos, expr = node
        return -_eval_rec(expr, env)

    if tag == "bin":
        _, pos, op, left, right = node
        lv = _eval_rec(left, env)
        rv = _eval_rec(right, env)
        if op == "+":
            return lv + rv
        if op == "-":
            return lv - rv
        if op == "*":
            return lv * rv
        if op == "/":
            if rv == 0:
                raise _EvalError(pos, "division by zero")
            return lv // rv
        if op == "%":
            if rv == 0:
                raise _EvalError(pos, "division by zero")
            return lv % rv
        if op == "^":
            if rv < 0:
                raise _EvalError(pos, "negative exponent")
            if rv > 256:
                raise _EvalError(pos, "exponent too large")
            return lv ** rv
        raise RuntimeError(f"unknown binop {op}")

    if tag == "cmp":
        _, pos, op, left, right = node
        lv = _eval_rec(left, env)
        rv = _eval_rec(right, env)
        if op == "<":
            return 1 if lv < rv else 0
        if op == "<=":
            return 1 if lv <= rv else 0
        if op == ">":
            return 1 if lv > rv else 0
        if op == ">=":
            return 1 if lv >= rv else 0
        if op == "==":
            return 1 if lv == rv else 0
        if op == "!=":
            return 1 if lv != rv else 0
        raise RuntimeError(f"unknown cmpop {op}")

    if tag == "tern":
        _, _qpos, cond, a, b = node
        cv = _eval_rec(cond, env)
        if cv != 0:
            return _eval_rec(a, env)
        return _eval_rec(b, env)

    raise RuntimeError(f"unknown node {tag}")


# ---------------------------------------------------------------------------
# Driver
# ---------------------------------------------------------------------------

def _evaluate_impl(src: str, env: dict) -> tuple:
    tokens = _tokenize(src)
    try:
        ast = _Parser(tokens).parse_expr()
    except _ParseError as e:
        return ("error", e.pos, e.message)

    try:
        val = _eval_ast(ast, env)
    except _EvalError as e:
        return ("error", e.pos, e.message)

    return ("ok", val)

def leaderboard_ranks(submissions: list[tuple[str, int]]) -> list[int]:
    if not submissions:
        return []

    class Fenwick:
        def __init__(self, n: int) -> None:
            self.n = n
            self.tree = [0] * (n + 1)

        def add(self, i: int, delta: int) -> None:
            i += 1
            while i <= self.n:
                self.tree[i] += delta
                i += i & -i

        def prefix(self, i: int) -> int:
            """Sum of [0..i] inclusive (i may be -1 → 0)."""
            if i < 0:
                return 0
            i += 1
            s = 0
            while i > 0:
                s += self.tree[i]
                i -= i & -i
            return s

    # First pass: discover every (best, best_time) key that will ever be inserted
    player_best: dict[str, tuple[int, int]] = {}
    keys: list[tuple[int, int]] = []
    for i, (player, score) in enumerate(submissions):
        if player not in player_best:
            player_best[player] = (score, i)
            keys.append((score, i))
        else:
            best, t = player_best[player]
            if score > best:
                player_best[player] = (score, i)
                keys.append((score, i))

    # Order keys from best to worst; assign dense ranks
    keys.sort(key=lambda k: (-k[0], k[1]))
    key_to_idx = {k: idx for idx, k in enumerate(keys)}
    M = len(keys)
    fw = Fenwick(M)

    # Second pass: maintain the ordered set and answer ranks
    player_best.clear()
    result: list[int] = []
    for i, (player, score) in enumerate(submissions):
        if player not in player_best:
            player_best[player] = (score, i)
            fw.add(key_to_idx[(score, i)], 1)
        else:
            best, t = player_best[player]
            if score > best:
                fw.add(key_to_idx[(best, t)], -1)
                player_best[player] = (score, i)
                fw.add(key_to_idx[(score, i)], 1)

        cur_best, cur_t = player_best[player]
        idx = key_to_idx[(cur_best, cur_t)]
        better = fw.prefix(idx - 1)
        result.append(better + 1)

    return result

def count_records(levels: list[int], margin: int, queries: list[tuple[int, int]]) -> list[int]:
    n = len(levels)
    if not queries:
        return []
    if n == 0:
        return [0] * len(queries)

    # Build sparse table for range maximum queries (O(1) after O(n log n) build)
    LOG = (n).bit_length() + 1
    st = [levels[:]]
    for k in range(1, LOG):
        prev = st[k - 1]
        shift = 1 << (k - 1)
        curr = [0] * n
        for i in range(n):
            if i + shift < n:
                curr[i] = max(prev[i], prev[i + shift])
            else:
                curr[i] = prev[i]
        st.append(curr)

    def range_max(l: int, r: int) -> int:
        if l > r or l >= n:
            return -10**18 - 10**9  # smaller than any possible A[i] + margin
        length = r - l + 1
        k = length.bit_length() - 1
        return max(st[k][l], st[k][r - (1 << k) + 1])

    # Compute next[i] = smallest j > i with levels[j] >= levels[i] + margin, or n
    next_pos = [n] * n
    for i in range(n):
        thresh = levels[i] + margin
        lo = i + 1
        hi = n
        while lo < hi:
            mid = (lo + hi) // 2
            if range_max(i + 1, mid) >= thresh:
                hi = mid
            else:
                lo = mid + 1
        next_pos[i] = lo if lo < n else n

    # Binary lifting: jump[k][i] = the position after 2^k steps following next
    LOGJ = 18  # 2^18 > 200000
    jump = [[n] * n for _ in range(LOGJ)]
    for i in range(n):
        jump[0][i] = next_pos[i]
    for k in range(1, LOGJ):
        prev = jump[k - 1]
        curr = jump[k]
        for i in range(n):
            j = prev[i]
            curr[i] = prev[j] if j < n else n

    # Answer each query by binary lifting along the next-path while staying <= r
    ans = []
    for l, r in queries:
        pos = l
        cnt = 1
        for k in range(LOGJ - 1, -1, -1):
            nxt = jump[k][pos]
            if nxt <= r:
                pos = nxt
                cnt += 1 << k
        ans.append(cnt)
    return ans

def format_base(p: int, q: int, base: int, k: int) -> str:
    if q == 0 or not (2 <= base <= 36) or k < 0:
        raise ValueError("invalid argument")

    DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"

    if p == 0:
        return "0"

    negative = (p < 0) != (q < 0)
    p = abs(p)
    q = abs(q)

    power = pow(base, k)
    N, rem = divmod(p * power, q)

    # Round half to even (parity of N itself)
    if rem * 2 > q or (rem * 2 == q and N % 2 == 1):
        N += 1

    if N == 0:
        return "0"

    int_part = N // power
    frac_part = N % power

    # Integer part (small: O(|p/q|), slow conversion is fine)
    if int_part == 0:
        int_str = "0"
    else:
        chars = []
        x = int_part
        while x:
            x, d = divmod(x, base)
            chars.append(DIGITS[d])
        int_str = "".join(reversed(chars))

    if frac_part == 0:
        result = int_str
    else:
        # Fixed-width base conversion via divide-and-conquer.
        # Split widths at powers of two so only O(log k) splitters are needed.
        pow2exp = [base]  # pow2exp[i] = base ** (2 ** i)
        e = 1
        while e * 2 < k:
            pow2exp.append(pow2exp[-1] * pow2exp[-1])
            e *= 2

        def frac_digits(n: int, width: int) -> list:
            if width == 0:
                return []
            if width == 1:
                return [DIGITS[n]]
            mid = 1
            idx = 0
            while mid * 2 < width:
                mid *= 2
                idx += 1
            hi, lo = divmod(n, pow2exp[idx])
            return frac_digits(hi, width - mid) + frac_digits(lo, mid)

        frac_chars = frac_digits(frac_part, k)
        while frac_chars and frac_chars[-1] == "0":
            frac_chars.pop()
        if frac_chars:
            result = int_str + "." + "".join(frac_chars)
        else:
            result = int_str

    if negative:
        result = "-" + result
    return result

import re
from fractions import Fraction
from math import gcd

def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    if max_num < 0 or max_den < 1:
        raise ValueError("invalid bounds")
    val = _parse_literal(x)
    if val == 0 or max_num == 0:
        return "0/1"
    neg = val < 0
    abs_val = -val if neg else val
    a, b = _closest_positive(abs_val, max_num, max_den)
    if neg:
        a = -a
    return f"{a}/{b}"


def _parse_literal(s: str) -> Fraction:
    match = re.fullmatch(r'([+-])?(\d+\.?|\.\d+|\d+\.\d+)([eE]([+-]?\d+))?', s)
    if match is None:
        raise ValueError("invalid literal")
    sign_s, mant_s, _, exp_num_s = match.groups()
    sign = -1 if sign_s == '-' else 1
    if '.' in mant_s:
        intpart, fracpart = mant_s.split('.', 1)
        digits_str = intpart + fracpart
        places = len(fracpart)
        mant_val = Fraction(int(digits_str), 10 ** places)
    else:
        mant_val = Fraction(int(mant_s))
    if exp_num_s is not None:
        e = int(exp_num_s)
        if e >= 0:
            mant_val *= 10 ** e
        else:
            mant_val /= 10 ** (-e)
    return sign * mant_val


def _closest_positive(x: Fraction, N: int, D: int) -> tuple[int, int]:
    if x <= 0 or N <= 0:
        return 0, 1
    if x >= N:
        return N, 1
    p0, q0 = 0, 1
    p1, q1 = 1, 0
    n, d = x.numerator, x.denominator
    k = 0
    while True:
        if d == 0:
            g = gcd(p1, q1)
            return p1 // g, q1 // g
        if p1 == 0:
            kmax_n = (N + 1) if p0 <= N else -1
        else:
            kmax_n = (N - p0) // p1
        if q1 == 0:
            kmax_d = (D + 1) if q0 <= D else -1
        else:
            kmax_d = (D - q0) // q1
        a_bound = min(kmax_n, kmax_d)
        if a_bound < 0:
            k = 0
            break
        prod = a_bound * d if a_bound > 0 else 0
        if n > prod:
            k = a_bound
            break
        a = n // d
        p0, p1 = p1, p0 + a * p1
        q0, q1 = q1, q0 + a * q1
        n, d = d, n - a * d
    ca1 = p0 + k * p1
    cb1 = q0 + k * q1
    ca2 = p1
    cb2 = q1
    g1 = gcd(ca1, cb1) if cb1 else 1
    ba1, bb1 = ca1 // g1, cb1 // g1
    g2 = gcd(ca2, cb2) if cb2 else 1
    ba2, bb2 = ca2 // g2, cb2 // g2
    if bb1 == 0:
        return ba2, bb2
    if bb2 == 0:
        return ba1, bb1
    if ba1 * bb2 == ba2 * bb1:
        return ba1, bb1
    xn, xd = x.numerator, x.denominator
    err1 = abs(ba1 * xd - bb1 * xn)
    err2 = abs(ba2 * xd - bb2 * xn)
    left = err1 * bb2
    right = err2 * bb1
    if left < right:
        return ba1, bb1
    if right < left:
        return ba2, bb2
    if bb1 < bb2:
        return ba1, bb1
    if bb2 < bb1:
        return ba2, bb2
    if ba1 < ba2:
        return ba1, bb1
    return ba2, bb2

def decimal_to_half_bits(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError
    n = len(s)
    if n == 0:
        raise ValueError

    pos = 0
    sign = 0
    if s[pos] == '-':
        sign = 1
        pos += 1
    elif s[pos] == '+':
        pos += 1

    if pos >= n:
        raise ValueError

    saw_digit = False
    saw_dot = False
    dot_pos = 0
    digit_chars = []

    while pos < n:
        c = s[pos]
        if c == '.':
            if saw_dot:
                raise ValueError
            saw_dot = True
            dot_pos = len(digit_chars)
            pos += 1
            continue
        if '0' <= c <= '9':
            saw_digit = True
            digit_chars.append(c)
            pos += 1
            continue
        break

    if not saw_digit:
        raise ValueError

    exp10 = 0
    if pos < n:
        if s[pos] not in ('e', 'E'):
            raise ValueError
        pos += 1
        if pos >= n:
            raise ValueError
        exp_sign = 1
        if s[pos] == '-':
            exp_sign = -1
            pos += 1
        elif s[pos] == '+':
            pos += 1
        if pos >= n or not ('0' <= s[pos] <= '9'):
            raise ValueError
        exp_start = pos
        while pos < n and '0' <= s[pos] <= '9':
            pos += 1
        exp10 = exp_sign * int(s[exp_start:pos])

    if pos != n:
        raise ValueError

    dec_places = (len(digit_chars) - dot_pos) if saw_dot else 0
    digit_str = ''.join(digit_chars).lstrip('0')
    if not digit_str:
        return sign << 15

    sig = int(digit_str)
    exp10 -= dec_places
    nd = len(digit_str)

    INF = 0x7C00

    if exp10 >= 0:
        if exp10 + nd >= 7:
            return INF | (sign << 15)
        num = sig * (10 ** exp10)
        den = 1
    else:
        if exp10 + nd <= -10:
            return sign << 15
        num = sig
        den = 10 ** (-exp10)

    def cmp_pow2(p: int) -> int:
        if p >= 0:
            t = den << p
            return (num > t) - (num < t)
        else:
            t = num << (-p)
            return (t > den) - (t < den)

    e = num.bit_length() - den.bit_length()
    while cmp_pow2(e) < 0:
        e -= 1
    while cmp_pow2(e + 1) >= 0:
        e += 1

    def round_div(n: int, d: int) -> int:
        q, r = divmod(n, d)
        if r == 0:
            return q
        twice_r = r << 1
        if twice_r > d or (twice_r == d and (q & 1)):
            q += 1
        return q

    if e >= 16:
        return INF | (sign << 15)

    if e >= -14:
        scale = 10 - e
        if scale >= 0:
            q = round_div(num << scale, den)
        else:
            q = round_div(num, den << (-scale))
        if q == 2048:
            q = 1024
            e += 1
        if e > 15:
            return INF | (sign << 15)
        biased = e + 15
        frac = q - 1024
        return (biased << 10) | frac | (sign << 15)
    else:
        q = round_div(num << 24, den)
        if q >= 1024:
            return 0x0400 | (sign << 15)
        if q == 0:
            return sign << 15
        return q | (sign << 15)

import random

class Node:
    __slots__ = ('key', 'val', 'left', 'right', 'pri', 'size', 'sum', 'min_key', 'max_key')

    def __init__(self, key, val, left=None, right=None, pri=None):
        self.key = key
        self.val = val
        self.left = left
        self.right = right
        self.pri = random.random() if pri is None else pri
        self.size = 1
        self.sum = val
        self.min_key = key
        self.max_key = key
        self._recalc()

    def _recalc(self):
        self.size = 1
        self.sum = self.val
        self.min_key = self.key
        self.max_key = self.key
        if self.left is not None:
            self.size += self.left.size
            self.sum += self.left.sum
            self.min_key = self.left.min_key
        if self.right is not None:
            self.size += self.right.size
            self.sum += self.right.sum
            self.max_key = self.right.max_key


def split(node, key):
    if node is None:
        return None, None
    if node.key < key:
        l, r = split(node.right, key)
        new_node = Node(node.key, node.val, node.left, l, node.pri)
        return new_node, r
    else:
        l, r = split(node.left, key)
        new_node = Node(node.key, node.val, r, node.right, node.pri)
        return l, new_node


def merge(left, right):
    if left is None:
        return right
    if right is None:
        return left
    if left.pri > right.pri:
        new_right = merge(left.right, right)
        return Node(left.key, left.val, left.left, new_right, left.pri)
    else:
        new_left = merge(left, right.left)
        return Node(right.key, right.val, new_left, right.right, right.pri)


def insert(root, key, val):
    l, r = split(root, key)
    _, r = split(r, key + 1)
    return merge(merge(l, Node(key, val)), r)


def delete(root, key):
    l, r = split(root, key)
    mid, r = split(r, key + 1)
    if mid is None:
        return None
    return merge(l, r)


def get(node, key):
    while node is not None:
        if key == node.key:
            return node.val
        node = node.left if key < node.key else node.right
    return None


def kth(node, k):
    if node is None or k < 1 or k > node.size:
        return None
    left_size = node.left.size if node.left is not None else 0
    if k <= left_size:
        return kth(node.left, k)
    if k == left_size + 1:
        return node.key
    return kth(node.right, k - left_size - 1)


def range_sum(node, lo, hi):
    if node is None or lo > hi:
        return 0
    if node.max_key < lo or node.min_key > hi:
        return 0
    if lo <= node.min_key and node.max_key <= hi:
        return node.sum
    res = 0
    if lo <= node.key <= hi:
        res += node.val
    res += range_sum(node.left, lo, hi)
    res += range_sum(node.right, lo, hi)
    return res


def range_count(node, lo, hi):
    if node is None or lo > hi:
        return 0
    if node.max_key < lo or node.min_key > hi:
        return 0
    if lo <= node.min_key and node.max_key <= hi:
        return node.size
    res = 0
    if lo <= node.key <= hi:
        res += 1
    res += range_count(node.left, lo, hi)
    res += range_count(node.right, lo, hi)
    return res


def run_ops(ops: list[tuple]) -> list:
    roots = [None]
    output = []
    for op in ops:
        typ = op[0]
        v = op[1]
        if not (0 <= v < len(roots)):
            output.append("BADVER")
            continue
        root = roots[v]
        if typ == "set":
            key, value = op[2], op[3]
            new_root = insert(root, key, value)
            roots.append(new_root)
            output.append(len(roots) - 1)
        elif typ == "del":
            key = op[2]
            new_root = delete(root, key)
            if new_root is None:
                output.append("NOKEY")
            else:
                roots.append(new_root)
                output.append(len(roots) - 1)
        elif typ == "get":
            key = op[2]
            output.append(get(root, key))
        elif typ == "count":
            lo, hi = op[2], op[3]
            output.append(range_count(root, lo, hi))
        elif typ == "sum":
            lo, hi = op[2], op[3]
            output.append(range_sum(root, lo, hi))
        elif typ == "kth":
            k = op[2]
            output.append(kth(root, k))
    return output

def run_ops(ops: list[tuple]) -> list:
    import heapq

    vals = set()
    for op in ops:
        if op[0] in ("add", "remove", "count_less"):
            vals.add(op[1])
    coord = sorted(vals)
    m = len(coord)
    rank = {v: i + 1 for i, v in enumerate(coord)}

    LC = [0]
    RC = [0]
    SM = [0]
    DT = [0]

    def update(node, l, r, pos, delta):
        newn = len(LC)
        LC.append(0)
        RC.append(0)
        SM.append(0)
        DT.append(0)
        if l == r:
            nsm = SM[node] + delta
            SM[newn] = nsm
            DT[newn] = 1 if nsm > 0 else 0
            return newn
        mid = (l + r) // 2
        lc = LC[node]
        rc = RC[node]
        if pos <= mid:
            lc = update(lc, l, mid, pos, delta)
        else:
            rc = update(rc, mid + 1, r, pos, delta)
        LC[newn] = lc
        RC[newn] = rc
        SM[newn] = SM[lc] + SM[rc]
        DT[newn] = DT[lc] + DT[rc]
        return newn

    def query_sum(node, l, r, ql, qr):
        if node == 0 or ql > qr or ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return SM[node]
        mid = (l + r) // 2
        return (query_sum(LC[node], l, mid, ql, qr) +
                query_sum(RC[node], mid + 1, r, ql, qr))

    def get_count(node, l, r, pos):
        if node == 0:
            return 0
        if l == r:
            return SM[node]
        mid = (l + r) // 2
        if pos <= mid:
            return get_count(LC[node], l, mid, pos)
        return get_count(RC[node], mid + 1, r, pos)

    def find_kth(node, l, r, k):
        if l == r:
            return l
        mid = (l + r) // 2
        leftsm = SM[LC[node]]
        if k <= leftsm:
            return find_kth(LC[node], l, mid, k)
        return find_kth(RC[node], mid + 1, r, k - leftsm)

    current = 0
    results = []
    cp_roots = [None]
    is_valid = [False]
    maxh = []
    cp_id_counter = 0

    for op in ops:
        typ = op[0]
        if typ == "add":
            x = op[1]
            rx = rank[x]
            current = update(current, 1, m, rx, 1)
            results.append(SM[current])
        elif typ == "remove":
            x = op[1]
            rx = rank[x]
            cnt = get_count(current, 1, m, rx)
            if cnt > 0:
                current = update(current, 1, m, rx, -1)
                results.append(True)
            else:
                results.append(False)
        elif typ == "checkpoint":
            cp_id_counter += 1
            cp_roots.append(current)
            is_valid.append(True)
            heapq.heappush(maxh, -cp_id_counter)
            results.append(cp_id_counter)
        elif typ == "rollback":
            c = op[1]
            if not (1 <= c < len(is_valid) and is_valid[c]):
                results.append("BADCP")
            else:
                current = cp_roots[c]
                while maxh and -maxh[0] > c:
                    iid = -heapq.heappop(maxh)
                    is_valid[iid] = False
                results.append(SM[current])
        elif typ == "median":
            s = SM[current]
            if s == 0:
                results.append(None)
            else:
                k = (s + 1) // 2
                rnk = find_kth(current, 1, m, k)
                results.append(coord[rnk - 1])
        elif typ == "count_less":
            x = op[1]
            rx = rank[x]
            if rx <= 1:
                res = 0
            else:
                res = query_sum(current, 1, m, 1, rx - 1)
            results.append(res)
        elif typ == "distinct":
            results.append(DT[current])

    return results

def run_ops(ops: list[tuple]) -> list:
    import random
    import sys
    sys.setrecursionlimit(100000)

    class Node:
        __slots__ = ('s', 'e', 'pri', 'left', 'right', 'sum_len', 'max_gap', 'min_s', 'max_e')
        def __init__(self, s, e):
            self.s = s
            self.e = e
            self.pri = random.random()
            self.left = None
            self.right = None
            self.sum_len = e - s
            self.max_gap = 0
            self.min_s = s
            self.max_e = e

        def update(self):
            self.sum_len = self.e - self.s
            self.min_s = self.s
            self.max_e = self.e
            self.max_gap = 0
            if self.left is not None:
                self.sum_len += self.left.sum_len
                self.min_s = self.left.min_s
                self.max_gap = max(self.max_gap, self.left.max_gap, self.s - self.left.max_e)
            if self.right is not None:
                self.sum_len += self.right.sum_len
                self.max_e = self.right.max_e
                self.max_gap = max(self.max_gap, self.right.max_gap, self.right.min_s - self.e)

    def split(node, key):
        if node is None:
            return None, None
        if node.s < key:
            l, r = split(node.right, key)
            node.right = l
            node.update()
            return node, r
        else:
            l, r = split(node.left, key)
            node.left = r
            node.update()
            return l, node

    def merge(left, right):
        if left is None:
            return right
        if right is None:
            return left
        if left.pri > right.pri:
            left.right = merge(left.right, right)
            left.update()
            return left
        else:
            right.left = merge(left, right.left)
            right.update()
            return right

    def find_first(node, t, d, prev_end):
        if node is None:
            return None
        entry_gap = node.min_s - prev_end
        if node.max_e <= t or max(node.max_gap, entry_gap) < d:
            return None
        res = find_first(node.left, t, d, prev_end)
        if res is not None:
            return res
        curr_prev = node.left.max_e if node.left is not None else prev_end
        x = max(t, curr_prev)
        if node.s - x >= d:
            return x
        return find_first(node.right, t, d, node.e)

    root = None
    output = []
    for op in ops:
        typ = op[0]
        if typ == "book":
            s, e = op[1], op[2]
            if s >= e:
                output.append("INVALID")
                continue
            left, right = split(root, s)
            conflict = (left is not None and left.max_e > s) or (right is not None and right.min_s < e)
            if conflict:
                root = merge(left, right)
                output.append("CONFLICT")
            else:
                new_node = Node(s, e)
                root = merge(merge(left, new_node), right)
                output.append(True)
        elif typ == "cancel":
            s = op[1]
            left, right = split(root, s)
            if right is None or right.min_s != s:
                root = merge(left, right)
                output.append(0)
            else:
                mid, right2 = split(right, s + 1)
                length = mid.e - mid.s
                root = merge(left, right2)
                output.append(length)
        elif typ == "first_fit":
            t, d = op[1], op[2]
            if root is None:
                output.append(t)
            else:
                ans = find_first(root, t, d, -1)
                if ans is None:
                    ans = max(t, root.max_e)
                output.append(ans)
        elif typ == "free_between":
            a, b = op[1], op[2]
            if a >= b:
                output.append(0)
                continue
            left, right = split(root, b)
            ll, lr = split(left, a)
            booked = 0
            if ll is not None and ll.max_e > a:
                booked += min(ll.max_e, b) - a
            if lr is not None:
                booked += lr.sum_len
                if lr.max_e > b:
                    booked -= lr.max_e - b
            root = merge(merge(ll, lr), right)
            output.append((b - a) - booked)
    return output

from sortedcontainers import SortedDict

def run_ops(ops: list[tuple]) -> list:
    sd = SortedDict()  # start -> (end, label); disjoint, merged adjacent same-label runs
    totals = {}  # label -> total length
    res = []

    def split(pos: int) -> None:
        i = sd.bisect_right(pos) - 1
        if i < 0:
            return
        s = sd.keys()[i]
        e, lab = sd[s]
        if not (s < pos < e):
            return
        del sd[s]
        sd[s] = (pos, lab)
        sd[pos] = (e, lab)

    def merge_after_insert(l: int, r: int, lab: str) -> None:
        # sd[l] == (r, lab) was just inserted; merge with immediate neighbours if possible
        i = sd.bisect_left(l)
        if i > 0:
            prev_s = sd.keys()[i - 1]
            prev_e, prev_lab = sd[prev_s]
            if prev_e == l and prev_lab == lab:
                del sd[l]
                sd[prev_s] = (r, lab)
                l = prev_s
        i = sd.bisect_left(l)
        if i + 1 < len(sd):
            next_s = sd.keys()[i + 1]
            if next_s == r:
                next_e, next_lab = sd[next_s]
                if next_lab == lab:
                    del sd[next_s]
                    sd[l] = (next_e, lab)

    def apply_set(l: int, r: int, new_lab) -> int:
        if l >= r:
            return 0
        split(l)
        split(r)
        to_remove = list(sd.irange(l, r, inclusive=(True, False)))
        same = 0
        painted = 0
        for s in to_remove:
            e, lab = sd[s]
            length = e - s
            painted += length
            if new_lab is not None and lab == new_lab:
                same += length
            totals[lab] -= length
            if totals[lab] == 0:
                del totals[lab]
            del sd[s]
        if new_lab is not None:
            changed = (r - l) - same
            sd[l] = (r, new_lab)
            totals[new_lab] = totals.get(new_lab, 0) + (r - l)
            merge_after_insert(l, r, new_lab)
            return changed
        return painted

    def find_lab(p: int):
        i = sd.bisect_right(p) - 1
        if i >= 0:
            s = sd.keys()[i]
            e, lab = sd[s]
            if p < e:
                return lab
        return None

    def next_change(p: int):
        i = sd.bisect_right(p) - 1
        if i >= 0:
            s = sd.keys()[i]
            e, lab = sd[s]
            if p < e:
                return e
        j = sd.bisect_right(p)
        if j < len(sd):
            return sd.keys()[j]
        return None

    for op in ops:
        typ = op[0]
        if typ == "paint":
            _, l, r, label = op
            res.append(apply_set(l, r, label))
        elif typ == "erase":
            _, l, r = op
            res.append(apply_set(l, r, None))
        elif typ == "at":
            _, p = op
            res.append(find_lab(p))
        elif typ == "runs":
            res.append(len(sd))
        elif typ == "total":
            _, label = op
            res.append(totals.get(label, 0))
        elif typ == "next_change":
            _, p = op
            res.append(next_change(p))
    return res

from collections import OrderedDict
import heapq


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    # key -> (value, expires_at, ver); OrderedDict maintains LRU (oldest use first)
    store = OrderedDict()
    heap = []  # (expires_at, ver, key) — lazy expiry; ver ignores stale heap entries
    out = []
    last_t = None
    ver_counter = 0

    def purge(t):
        """Remove all entries whose expires_at <= t (no longer alive at t)."""
        while heap and heap[0][0] <= t:
            exp, ver, k = heapq.heappop(heap)
            cur = store.get(k)
            if cur is not None and cur[2] == ver:
                del store[k]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (not isinstance(ttl, int) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
            expires_at = None if ttl is None else t + ttl

            purge(t)

            ver_counter += 1
            ver = ver_counter

            if key in store:
                # Existing unexpired entry: replace value/expiry; put counts as a USE
                store[key] = (value, expires_at, ver)
                store.move_to_end(key)
            else:
                # Insert; evict LRU unexpired if already at capacity
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = (value, expires_at, ver)

            if expires_at is not None:
                heapq.heappush(heap, (expires_at, ver, key))

        elif kind == "get":
            key = op[2]
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                value, expires_at, _ver = entry
                # Alive only while t < expires_at (dead for all T >= expires_at)
                if expires_at is not None and t >= expires_at:
                    del store[key]
                    out.append(None)
                else:
                    store.move_to_end(key)
                    out.append(value)

        elif kind == "size":
            purge(t)
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

import heapq
from collections import defaultdict


def window_medians(readings, k):
    if not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: the smaller half; top is the lower median
    high = []   # min-heap: the larger half
    delayed = defaultdict(int)  # value -> pending lazy deletions
    sizes = {"low": 0, "high": 0}  # live (not yet deleted) element counts
    out = []

    def prune(heap, sign):
        # drop deleted values sitting on top of a heap
        while heap and delayed[sign * heap[0]]:
            delayed[sign * heap[0]] -= 1
            if delayed[sign * heap[0]] == 0:
                del delayed[sign * heap[0]]
            heapq.heappop(heap)

    def rebalance():
        # invariant: sizes["low"] == sizes["high"] or sizes["low"] == sizes["high"] + 1
        # tops of both heaps are kept free of delayed values
        if sizes["low"] > sizes["high"] + 1:
            heapq.heappush(high, -heapq.heappop(low))
            sizes["low"] -= 1
            sizes["high"] += 1
            prune(low, -1)
        elif sizes["low"] < sizes["high"]:
            heapq.heappush(low, -heapq.heappop(high))
            sizes["high"] -= 1
            sizes["low"] += 1
            prune(high, 1)

    def add(x):
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            sizes["low"] += 1
        else:
            heapq.heappush(high, x)
            sizes["high"] += 1
        rebalance()

    def remove(x):
        delayed[x] += 1
        # attribute the deletion to the half that must contain x under the invariant
        # (all in low <= all in high; equals of the median may sit in either half —
        # rebalance corrects the size counters if the physical copy was in the other half)
        if low and x <= -low[0]:
            sizes["low"] -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            sizes["high"] -= 1
            if high and x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        # slide the window regardless of whether the incoming reading is None
        if i >= k and readings[i - k] is not None:
            remove(readings[i - k])
        prune(low, -1)
        out.append(-low[0] if sizes["low"] else None)
    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            if end == -1:
                i = n
            else:
                i = end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j < n and src[j] == "." and j + 1 < n and _is_digit(src[j + 1]):
                j += 1
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
